// Writes a Dockerfile for a repository that has none, so the deploy action can
// build it. Covers Next.js apps (standalone output when next.config asks for it)
// and other Node.js apps with a "start" script. Anything else is refused with a
// message: the Dockerfile is the build recipe Gust trusts, and a guess here
// would ship the wrong image.
//
// Usage: node dockerfile.mjs <context-dir> <out-dir>
// Writes <out-dir>/Dockerfile and <out-dir>/Dockerfile.dockerignore, prints the
// Dockerfile path. Uses only Node built-ins, so it runs on any runner.

import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

export const NODE_IMAGE = 'node:24-slim';

/**
 * @typedef {{ files: Set<string>, pkg: any, nextConfig?: string, yarnLock?: string }} Input
 */

/** Which package manager, and which version of it, the repository pins. */
function packageManager(files, pkg) {
  const field = typeof pkg.packageManager === 'string' ? pkg.packageManager : '';
  const m = /^([a-z]+)@([^+\s]+)/.exec(field);
  if (m && !['npm', 'pnpm', 'yarn'].includes(m[1])) {
    throw new Error(`packageManager is ${m[1]}. Only npm, pnpm and yarn are built without a Dockerfile.`);
  }
  if (m) return { name: m[1], version: m[2] };
  if (files.has('pnpm-lock.yaml')) return { name: 'pnpm', version: null };
  if (files.has('yarn.lock')) return { name: 'yarn', version: null };
  return { name: 'npm', version: null };
}

/** The install, prune and cache lines for one package manager. */
function tooling({ name, version }, files, yarnLock) {
  const lock = { npm: 'package-lock.json', pnpm: 'pnpm-lock.yaml', yarn: 'yarn.lock' }[name];
  const hasLock = files.has(lock);
  if (name === 'pnpm') {
    const pinned = version ?? '12';
    const major = Number(pinned.split('.')[0]);
    const frozen = hasLock ? ' --frozen-lockfile' : '';
    // pnpm 11 and later fail an install while a dependency's build scripts await
    // approval, and only a failed install lists them. So the first attempt may
    // fail; the approval step then approves them all, and the last install runs
    // the scripts. The image is a throwaway build, so approving everything here
    // does not reach the app. A failure that is not about approval still fails at
    // the last install. pnpm 10 has no --all and installs without failing; pnpm
    // 9 and older do not have the approval step at all.
    const install =
      major >= 11 ? `(pnpm install${frozen} || true) && pnpm approve-builds --all && pnpm install${frozen}` : `pnpm install${frozen}`;
    return {
      lock: hasLock ? lock : null,
      global: `npm install -g pnpm@${pinned}`,
      install,
      cache: { target: '/root/.local/share/pnpm/store', id: 'pnpm' },
      prune: 'pnpm prune --prod',
    };
  }
  if (name === 'yarn') {
    // Yarn Berry (2+) has its own lockfile format, marked by __metadata.
    const berry = version ? Number(version.split('.')[0]) >= 2 : yarnLock.includes('__metadata:');
    if (berry) {
      return {
        lock: hasLock ? lock : null,
        global: `npm install -g yarn@${version ?? '4'}`,
        install: hasLock ? 'yarn install --immutable' : 'yarn install',
        cache: null,
        prune: null, // Berry has no prune; devDependencies stay in the image.
      };
    }
    return {
      lock: hasLock ? lock : null,
      global: `npm install -g yarn@${version ?? '1'}`,
      install: hasLock ? 'yarn install --frozen-lockfile' : 'yarn install',
      cache: { target: '/usr/local/share/.cache/yarn', id: 'yarn' },
      prune: hasLock ? 'yarn install --production --frozen-lockfile' : 'yarn install --production',
    };
  }
  return {
    lock: hasLock ? lock : null,
    global: null,
    install: hasLock ? 'npm ci' : 'npm install',
    cache: { target: '/root/.npm', id: 'npm' },
    prune: 'npm prune --omit=dev',
  };
}

/**
 * Plans the Dockerfile and its .dockerignore from what the repository holds.
 * Pure: no file access, so it can be tested with plain objects.
 * @param {Input} input
 * @returns {{ dockerfile: string, dockerignore: string, kind: 'next' | 'node' }}
 */
export function planDockerfile({ files, pkg, nextConfig = '', yarnLock = '' }) {
  if (!pkg) throw new Error('No Dockerfile and no package.json. Add a Dockerfile; Gust builds only from one.');
  const pm = packageManager(files, pkg);
  const tool = tooling(pm, files, yarnLock);
  const scripts = pkg.scripts ?? {};
  const isNext = Boolean(pkg.dependencies?.next || pkg.devDependencies?.next);
  if (!isNext && !scripts.start) {
    throw new Error('No Dockerfile, and package.json has neither a Next.js dependency nor a "start" script. Add a Dockerfile.');
  }
  const standalone = isNext && /output\s*:\s*["']standalone["']/.test(nextConfig);
  const hasPublic = files.has('public');

  const L = [];
  L.push('# Generated by Gust: the repository has no Dockerfile. Add one to take over the build.');
  L.push('');
  L.push('# Build stage: install everything, build, then drop dev dependencies.');
  L.push(`FROM ${NODE_IMAGE} AS build`);
  L.push('WORKDIR /app');
  if (tool.global) L.push(`RUN ${tool.global}`);
  // Manifests first, so the install layer is reused until dependencies change.
  L.push(`COPY package.json${tool.lock ? ` ${tool.lock}` : ''} ./`);
  const install = `RUN ${tool.cache ? `--mount=type=cache,id=${tool.cache.id},target=${tool.cache.target} ` : ''}${tool.install}`;
  L.push(install);
  L.push('COPY . .');
  if (isNext) L.push('ENV NEXT_TELEMETRY_DISABLED=1');
  if (scripts.build) L.push(`RUN ${pm.name} run build`);
  else if (isNext) L.push('RUN node node_modules/next/dist/bin/next build');
  if (tool.prune) L.push(`RUN ${tool.prune}`);
  L.push('');

  L.push('# Run stage: only what the app needs to start, as a non-root user.');
  L.push(`FROM ${NODE_IMAGE} AS run`);
  L.push('WORKDIR /app');
  // The engine's Docker health check runs curl or wget inside the container, and
  // node:slim has neither, so every deploy would be marked unhealthy.
  L.push('RUN apt-get update && apt-get install -y --no-install-recommends curl && rm -rf /var/lib/apt/lists/*');
  L.push('ENV NODE_ENV=production PORT=3000');
  if (isNext) L.push('ENV NEXT_TELEMETRY_DISABLED=1');

  if (standalone) {
    // next.config sets output: 'standalone', so .next/standalone holds server.js and its own node_modules.
    L.push('ENV HOSTNAME=0.0.0.0');
    L.push('USER node');
    L.push('COPY --from=build --chown=node:node /app/.next/standalone ./');
    L.push('COPY --from=build --chown=node:node /app/.next/static ./.next/static');
    if (hasPublic) L.push('COPY --from=build --chown=node:node /app/public ./public');
    L.push('EXPOSE 3000');
    L.push('CMD ["node", "server.js"]');
  } else if (isNext) {
    L.push('USER node');
    L.push('COPY --from=build --chown=node:node /app ./');
    L.push('EXPOSE 3000');
    L.push('CMD ["node", "node_modules/next/dist/bin/next", "start", "-H", "0.0.0.0", "-p", "3000"]');
  } else {
    // The app listens on PORT (3000 here); the start script decides the rest.
    if (pm.name !== 'npm') L.push(`RUN ${tool.global}`);
    L.push('USER node');
    L.push('COPY --from=build --chown=node:node /app ./');
    L.push('EXPOSE 3000');
    L.push(`CMD ["${pm.name}", "start"]`);
  }
  L.push('');

  const dockerignore = [
    '.git',
    '.github',
    '**/node_modules',
    '**/.next',
    '**/.env',
    '**/.env.local',
    '**/.env.*.local',
    '**/*.log',
    '**/.DS_Store',
    '**/coverage',
    'Dockerfile',
    'Dockerfile.dockerignore',
    '',
  ].join('\n');

  return { dockerfile: L.join('\n'), dockerignore, kind: isNext ? 'next' : 'node' };
}

function main() {
  const [context = '.', outDir] = process.argv.slice(2);
  if (!outDir) {
    console.error('Usage: node dockerfile.mjs <context-dir> <out-dir>');
    process.exit(2);
  }
  const root = resolve(context);
  const files = new Set(readdirSync(root));
  const read = (name) => (files.has(name) ? readFileSync(join(root, name), 'utf8') : '');
  const pkg = files.has('package.json') ? JSON.parse(read('package.json')) : null;
  const configName = ['next.config.js', 'next.config.mjs', 'next.config.cjs', 'next.config.ts'].find((f) => files.has(f));
  const plan = planDockerfile({
    files,
    pkg,
    nextConfig: configName ? read(configName) : '',
    yarnLock: read('yarn.lock'),
  });
  mkdirSync(outDir, { recursive: true });
  const dockerfile = join(outDir, 'Dockerfile');
  writeFileSync(dockerfile, plan.dockerfile);
  // BuildKit reads <Dockerfile>.dockerignore next to the Dockerfile, so the
  // ignore rules apply even though the file lives outside the build context.
  writeFileSync(`${dockerfile}.dockerignore`, plan.dockerignore);
  console.log(dockerfile);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  try {
    main();
  } catch (e) {
    // stderr: the caller captures stdout (the path), and the message must still reach the log.
    console.error(`::error::${e.message}`);
    process.exit(1);
  }
}
